class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for v in arr:
        node = ListNode(v)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def list_to_arr(head):
    result = []
    node = head
    while node:
        result.append(node.val)
        node = node.next
    return result


def add_two_numbers(l1_arr, l2_arr):
    l1 = arr_to_list(l1_arr)
    l2 = arr_to_list(l2_arr)

    stack1, stack2 = [], []
    node = l1
    while node:
        stack1.append(node.val)
        node = node.next
    node = l2
    while node:
        stack2.append(node.val)
        node = node.next

    carry = 0
    result_head = None
    while stack1 or stack2 or carry:
        v1 = stack1.pop() if stack1 else 0
        v2 = stack2.pop() if stack2 else 0
        total = v1 + v2 + carry
        carry = total // 10
        result_head = ListNode(total % 10, result_head)

    return list_to_arr(result_head)

